// Remembers the newest inquiry already sent (workflow static data; persists for the active workflow).
const s = $getWorkflowStaticData('global');
if (!s.since) s.since = new Date().toISOString(); // first run: start from now, do not replay history
return [{ json: { since: s.since } }];

const __out = [];
const __items = $input.all();
for (let __k = 0; __k < __items.length; __k++) {
  const $json = __items[__k].json;
  const __r = (() => {
    const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const q = $json; if (!q || !q.id) return [];
    const SITE = 'https://vip-realty.netlify.app';
    const lines = ['📩 <b>Նոր հարցում կայքից</b>', '👤 ' + esc(q.name)];
    if (q.phone) lines.push('📞 ' + esc(q.phone));
    if (q.email) lines.push('✉️ ' + esc(q.email));
    if (q.property?.slug) lines.push('🏠 ' + SITE + '/properties/' + esc(q.property.slug));
    if (q.property?.agent?.name) lines.push('🧑‍💼 Գործակալ՝ ' + esc(q.property.agent.name) + (q.property.agent.phone ? ' · ' + esc(q.property.agent.phone) : ''));
    if (q.message) lines.push('', esc(String(q.message).slice(0, 800)));
    lines.push('', '🗂 ' + SITE + '/admin/inquiries');
    return [{ json: { text: lines.join('\n'), created_at: q.created_at } }];
  })();
  for (const x of (__r || [])) __out.push(x);
}
return __out;

// Only after the messages were sent: move the cursor to the newest inquiry delivered.
const s = $getWorkflowStaticData('global');
const times = $('Format inquiry').all().map((i) => i.json.created_at).filter(Boolean).sort();
if (times.length) s.since = times[times.length - 1];
return [{ json: { since: s.since, sent: times.length } }];
